typedef struct {
    f32 size;                  /* 0x00 */
    f32 amount;                /* 0x04 */
    f32 life;                  /* 0x08 seconds */
    s32 count;                 /* 0x0C */
    f32 spread_xy;             /* 0x10 */
    f32 spread_z;              /* 0x14 */
} MobyDirectionalPvars;

/* Exhaust vent: each frame emits a burst of smoke puffs from a random spot across the vent, blown out
 * along its facing; some are small fast sparks instead. */
void emit_moby_directional_particles(char *m) {
    struct Moby *moby = (struct Moby *)m;
    float pos[4];
    float vel[4];
    float off[4];
    MobyDirectionalPvars *pvars = (MobyDirectionalPvars *)moby->pvars;
    int i;
    moby->update_dist = 0x80;
    for (i = 0; i < pvars->count; i++) {
        int variant = random_integer_below(100) < *(int *)&orxon_vent_spark_percent;
        Vec4f *moby_position = &moby->pos;
        float x, y, z;
        float s;
        int c1, c2;
        qcopy(pos, moby_position);
        off[0] = FastCos(FastAddRots(moby->rot.z, 1.5707964f)) * random_float_between(-pvars->spread_xy, pvars->spread_xy);
        off[1] = FastSin(FastAddRots(moby->rot.z, 1.5707964f)) * random_float_between(-pvars->spread_xy, pvars->spread_xy);
        off[2] = 0.0f;
        off[2] = random_float_between(-pvars->spread_z, pvars->spread_z);
        FastVecAdd(pos, pos, off);
        x = random_float_between(*(float *)&orxon_vent_puff_speed_min, *(float *)&orxon_vent_puff_speed_max);
        y = random_float_between(*(float *)&orxon_vent_puff_speed_min, *(float *)&orxon_vent_puff_speed_max);
        z = random_float_between(*(float *)&orxon_vent_puff_speed_min, *(float *)&orxon_vent_puff_speed_max);
        if (x < y) x = y;
        if (x < z) x = z;
        BuildSphericalOffset(vel, x * g_frame_time, moby->rot.z, -moby->rot.y);
        if (variant) {
            FastVecScale(vel, vel, random_float_between(0.5f, 1.5f));
            s = pvars->amount * random_float_between(0.24f, 0.36f);
        } else {
            s = pvars->amount * random_float_between(0.8f, 1.2f);
        }
        c1 = FastTweenColor(*(int *)&orxon_vent_puff_color_a, *(int *)&orxon_vent_puff_color_b, random_float_between(0.5f, 1.0f));
        c2 = FastTweenColor(*(int *)&orxon_vent_puff_color_b, *(int *)&orxon_vent_puff_color_b & 0xFF000000, random_float_between(0.25f, 0.5f));
        spawn_gravity_floor_burst_particle(pos, vel, truncate_float_to_s32(multiply_global_factor(pvars->life * 60.0f)), s, pvars->size, *(float *)&directional_particle_gravity_gp * g_frame_time_sq, c1, c2, variant);
    }
}
