// Update of a pickup-style moby: waits for the player to come near, then spends bolts on a purchase.
void nanotech_upgrade_vendor_update(char *m) {
    Moby *moby = (Moby *)m;
    u8 *d = moby->pvars;
    Hero *g;
    unsigned char *alternate_item_available;

    fast_dec_timer((int *)(d + 4));
    switch (moby->state) {
    case 0:
        g = (Hero *)(hero_globals_base + 0xE1D);
        if (FastDiffRots(moby->rot.z, fast_atan2(g->motion.pos.f[0] - moby->pos.x, g->motion.pos.f[1] - moby->pos.y)) < 1.5707964f) {
            if (vec_distance_xy(&moby->pos, &g->motion.pos) < 4.0f) {
                if (*(int *)(d + 4) == 0) {
                    if (orxon_cinematic_mode != 2) {
                        set_moby_dialogue_record_value((char *)moby, 1);
                        alternate_item_available = special_items_base + 0x13B;
                        if (alternate_item_available[4] == 0) {
                            if (gBolts > 4000) {
                                int accepted = try_set_help_message(1, 0x271E) != 0;
                                if ((*(int *)(pad_globals_base + 0x2604) & 0x10) && accepted) {
                                    d = (u8 *)1;
                                    alternate_item_available[4] = (int)d;
                                    g->health.hp = 5;
                                    gBolts = gBolts - 4000;
                                    *(int *)&hero_max_health = 5;
                                    StartCutscene(0);
                                    moby->state = (int)d;
                                }
                            } else {
                                try_set_help_message(1, 0x2720);
                            }
                        } else if (alternate_item_available[5] == 0) {
                            if (*(int *)(d + 4) == 0) {
                                if (gBolts > 30000) {
                                    int accepted = try_set_help_message(1, 0x271F) != 0;
                                    if ((*(int *)(pad_globals_base + 0x2604) & 0x10) && accepted) {
                                        d = (u8 *)1;
                                        alternate_item_available[5] = (int)d;
                                        g->health.hp = 8;
                                        gBolts = gBolts - 30000;
                                        *(int *)&hero_max_health = 8;
                                        StartCutscene(1);
                                        moby->state = (int)d;
                                    }
                                } else {
                                    try_set_help_message(1, 0x2721);
                                }
                            }
                        }
                    }
                }
            }
        }
        break;
    case 1:
        if (orxon_cinematic_mode != 2) {
            memcard_Save(0, -1);
            ShowBanner(msgSel(), -1);
            *(int *)&dialogue_message_duration = 0xB4;
            *(int *)(d + 4) = scale_ticks(0xF0);
            moby->state = 0;
        }
        break;
    }
}

