extern struct L10Data orxon_cutscene_state;
extern void cutscene_set_camera_target(int);

/* update: wait for state 1, then act on the level's current mode */
void update_level_mode_dispatcher(char *m) {
    switch (*(unsigned char *)(m + 0x20)) {
    case 0:
        ((unsigned char *)m)[0x30] = 0xFF;
        m[0x20] = 1;
        break;
    case 1:
        if (orxon_cinematic_mode == 2) {
            if (orxon_cutscene_state.mode == 3 || orxon_cutscene_state.mode == 5 ||
                orxon_cutscene_state.mode == 6 || orxon_cutscene_state.mode == 7) {
                int v = orxon_cutscene_state.mode;
                int i;
                i = 0;
                if (v == 3) i = 1;
                else if (v == 5 || v == 6) i = 2;
                else if (v == 7) i = 3;
                cutscene_set_camera_target(orxon_cutscene_state.slot[i]);
            }
        }
        break;
    }
}
extern char *MobyGetHitMessage(void *, int, int);
extern int Moby_PlaySound(int, int, int);
extern void spawn_proximity_gated_bolts(void *);
extern void spawn_moby_break_fragments(void *, int, int, int, int, int, int);

/* Update for moby class 1855: waits, arms, then fires an effect and deletes itself. */
void Moby1855Update(char *m) {
    int hit = 0;
    char *r = MobyGetHitMessage(m, 0x10000, 0);
    switch (*(unsigned char *)(m + 0x20)) {
    case 0:
        m[0x20] = 1;
        break;
    case 1:
        if (r != 0 && *(float *)(r + 0x2C) > 0.0f) hit = 1;
        if (hit) m[0x20] = 2;
        break;
    case 2:
        Moby_PlaySound(0, 0, (int)m);
        spawn_proximity_gated_bolts(m);
        spawn_moby_break_fragments(m, 0x742, 1, 0x742, 1, 11, 2);
        DeleteMoby(m);
        break;
    }
}
extern void spawn_moby_from_placement(void *, int);

/* per-frame update: wait for a condition, then run, then clean up */
void update_hit_triggered_moby_spawner(char *moby) {
    int ok = 0;
    char *p = MobyGetHitMessage(moby, 0x10000, 0);
    switch (*(unsigned char *)(moby + 0x20)) {
    case 0:
        moby[0x20] = 1;
        break;
    case 1:
        if (p != 0) {
            if (0.0f < *(float *)(p + 0x2C)) ok = 1;
        }
        if (ok != 0) moby[0x20] = 2;
        break;
    case 2:
        Moby_PlaySound(0, 0, (int)moby);
        spawn_proximity_gated_bolts(moby);
        spawn_moby_from_placement(moby, 0x741);
        DeleteMoby(moby);
        break;
    }
}
/* Spawns a class 0x781 moby at the owner's position and returns it. */
char *spawn_destruction_replacement_moby(char *owner) {
    char *moby = CreateMoby(0x781);
    if (moby != 0) {
        ((unsigned char *)moby)[0x30] = 0xFF;
        *(short *)(moby + 0x32) = 0xFF;
        moby[0x31] = 1;
        *(int *)(moby + 0x40) = 0;
        *(int *)(moby + 0x44) = 0;
        *(float *)(moby + 0x48) = *(float *)(owner + 0x48);
        *(long *)(moby + 0x38) = *(long *)(owner + 0x38);
        qcopy(moby + 0x10, owner + 0x10);
        *(float *)(moby + 0x18) = 59.0f;
        moby_build_matrix(moby);
    }
    return moby;
}
